<script setup lang="ts">
import{computed,reactive,ref,watch}from'vue';import{Head,router,usePage}from'@inertiajs/vue3';import{route}from'ziggy-js';
interface Cliente{id:string;nombre:string;vehiculos:{id:string;label:string}[]}const props=defineProps<{clientes:Cliente[];servicios:{label:string;value:string}[];mecanicos:{label:string;value:string}[]}>();const state=reactive({clienteId:'',vehiculoId:'',fallaReportada:'',kilometraje:null as number|null,servicioIds:[]as string[],mecanicoIds:[]as string[]});const errors=computed<Record<string,string>>(()=>usePage().props.errors as Record<string,string>);const procesando=ref(false);const vehiculos=computed(()=>props.clientes.find(c=>c.id===state.clienteId)?.vehiculos??[]);watch(()=>state.clienteId,()=>state.vehiculoId='');function toggle(lista:string[],id:string,v:boolean){if(v&&!lista.includes(id))lista.push(id);if(!v){const i=lista.indexOf(id);if(i>=0)lista.splice(i,1)}}function guardar(){procesando.value=true;router.post(route('ordenes.store'),state,{onFinish:()=>procesando.value=false})}
</script>
<template><Head title="Nueva orden"/><UDashboardPanel><template #header><UDashboardNavbar title="Nueva orden de trabajo"/></template><template #body><form class="mx-auto max-w-5xl space-y-6" @submit.prevent="guardar"><UCard><template #header><h2 class="font-semibold">Recepción del vehículo</h2></template><div class="grid gap-5 md:grid-cols-2"><UFormField label="Cliente" required :error="errors.clienteId"><USelect v-model="state.clienteId" class="w-full" :items="clientes.map(c=>({label:c.nombre,value:c.id}))"/></UFormField><UFormField label="Vehículo" required :error="errors.vehiculoId"><USelect v-model="state.vehiculoId" class="w-full" :items="vehiculos.map(v=>({label:v.label,value:v.id}))"/></UFormField><UFormField label="Kilometraje" :error="errors.kilometraje"><UInput v-model.number="state.kilometraje" type="number" min="0" class="w-full"/></UFormField></div><UFormField class="mt-5" label="Falla reportada" required :error="errors.fallaReportada"><UTextarea v-model="state.fallaReportada" class="w-full" :rows="5"/></UFormField></UCard><UCard><template #header><h2 class="font-semibold">Servicios solicitados</h2></template><div class="grid gap-3 sm:grid-cols-2"><UCheckbox v-for="s in servicios" :key="s.value" :label="s.label" :model-value="state.servicioIds.includes(s.value)" @update:model-value="toggle(state.servicioIds,s.value,!!$event)"/></div><p v-if="errors.servicioIds" class="mt-3 text-sm text-error">{{errors.servicioIds}}</p></UCard><UCard><template #header><div><h2 class="font-semibold">Asignación inicial</h2><p class="text-sm text-muted">Opcional; puede realizarse luego.</p></div></template><div class="grid gap-3 sm:grid-cols-2"><UCheckbox v-for="m in mecanicos" :key="m.value" :label="m.label" :model-value="state.mecanicoIds.includes(m.value)" @update:model-value="toggle(state.mecanicoIds,m.value,!!$event)"/></div></UCard><div class="flex justify-end gap-3"><UButton type="button" label="Cancelar" color="neutral" variant="outline" @click="router.visit(route('ordenes.index'))"/><UButton type="submit" label="Crear orden" icon="i-lucide-save" :loading="procesando"/></div></form></template></UDashboardPanel></template>
